function columnLabel(n: number): string {
  let out = "";
  while (n > 0) {
    let rem = n % 26;
    n = Math.floor(n / 26);
    if (rem === 0) { rem = 26; n -= 1; } // Z, borrowed from the next place
    out = String.fromCharCode(64 + rem) + out;
  }
  return out;
}

