class Solution:
    def columnLabel(self, n: int) -> str:
        out = []
        while n > 0:
            n, rem = divmod(n, 26)
            if rem == 0:  # Z, borrowed from the next place
                rem = 26
                n -= 1
            out.append(chr(64 + rem))
        return "".join(reversed(out))

