function columnLabel(n: number): string {
  const letters: string[] = [];
  while (n > 0) {
    n--;
    letters.push(String.fromCharCode(65 + (n % 26)));
    n = Math.floor(n / 26);
  }
  return letters.reverse().join("");
}

